      "accountSubmit": {
        "title": "✅ Сохранить аккаунт",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">Проверьте данные и нажмите сохранение.</p><div style=\"padding: 8px 12px; background: #eff6ff; border-left: 3px solid #3b82f6; border-radius: 4px; font-size: 13px; margin-bottom: 12px;\"><b>📌 OAuth Flow:</b><ul style=\"margin: 8px 0 0 16px;\"><li>После сохранения будет переход на страницу провайдера</li><li>Выполните вход и авторизацию на странице провайдера</li><li>После успешной авторизации произойдёт автоматический возврат</li></ul></div><p style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>📌 Следующий шаг:</b> после добавления аккаунта создадим API-ключ</p><p style=\"margin-top: 12px; color: #10b981; font-weight: 600;\">👉 Нажмите кнопку \"Сохранить\"</p></div>"
      },
      "keyManage": {
        "title": "🔑 Шаг 3: Создать ключ",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\"><b>Поздравляем! Настройка аккаунта завершена 🎉</b></p><p style=\"margin-bottom: 12px;\">Последний шаг: создайте API Key, чтобы проверить работу сервиса.</p><div style=\"padding: 8px 12px; background: #eff6ff; border-left: 3px solid #3b82f6; border-radius: 4px; font-size: 13px; margin-bottom: 12px;\"><b>🔑 Назначение API Key:</b><ul style=\"margin: 8px 0 0 16px;\"><li>Учётные данные для вызова AI-сервисов</li><li>Каждый ключ привязан к одной группе</li><li>Можно задать квоту и срок действия</li><li>Поддерживает независимую статистику расхода</li></ul></div><p style=\"margin-top: 16px; color: #10b981; font-weight: 600;\">👉 Нажмите \"API-ключи\" в левом меню</p></div>"
      },
      "createKey": {
        "title": "➕ Создать ключ",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">Нажмите кнопку, чтобы создать первый API Key.</p><p style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>💡 Совет:</b> сразу скопируйте и сохраните ключ после создания — он показывается только один раз</p><p style=\"margin-top: 12px; color: #10b981; font-weight: 600;\">👉 Нажмите кнопку \"Создать ключ\"</p></div>"
      },
      "keyName": {
        "title": "✏️ 1. Название ключа",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">Задайте ключу удобное название.</p><p style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>💡 Примеры названий:</b> \"Test Key\", \"Production\", \"Mobile\" и т. д.</p></div>",
        "nextBtn": "Далее"
      },
      "keyGroup": {
        "title": "🎯 2. Выбор группы",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">Выберите группу, которую только что настроили.</p><div style=\"padding: 8px 12px; background: #eff6ff; border-left: 3px solid #3b82f6; border-radius: 4px; font-size: 13px; margin-bottom: 12px;\"><b>📌 Группа определяет:</b><ul style=\"margin: 8px 0 0 16px;\"><li>Какие аккаунты может использовать этот ключ</li><li>Какой тарифный коэффициент применяется</li><li>Является ли ключ эксклюзивным</li></ul></div><p style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>💡 Совет:</b> выберите тестовую группу, которую только что создали</p></div>",
        "nextBtn": "Далее"
      },
      "keySubmit": {
        "title": "🎉 Создать и скопировать",
        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">После нажатия на создание система сгенерирует полноценный API Key.</p><div style=\"padding: 8px 12px; background: #fee2e2; border-left: 3px solid #ef4444; border-radius: 4px; font-size: 13px; margin-bottom: 12px;\"><b>⚠️ Важно:</b><ul style=\"margin: 8px 0 0 16px;\"><li>Ключ показывается только один раз, скопируйте сразу</li><li>Если потеряете, потребуется сгенерировать заново</li><li>Храните безопасно и не передавайте другим</li></ul></div><div style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px; margin-bottom: 12px;\"><b>🚀 Следующие шаги:</b><ul style=\"margin: 8px 0 0 16px;\"><li>Скопируйте сгенерированный ключ sk-xxx</li><li>Используйте его в любом OpenAI-compatible клиенте</li><li>Начните пользоваться AI-сервисами!</li></ul></div><p style=\"margin-top: 12px; color: #10b981; font-weight: 600;\">👉 Нажмите кнопку \"Создать\"</p></div>"
      }
